using System;using System.Linq;using System.IO;using System.Reflection;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.UIElements;using EchoSphere.Core;using EchoSphere.Runtime;using EchoSphere.Presentation;
public static class ArchiveProgressionCheck {
 const BindingFlags F=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance|BindingFlags.Static;
 public static object Main(){if(!Application.isPlaying)throw new Exception("Play required");int checks=0;void Check(bool value,string why){checks++;if(!value)throw new Exception(why);}void Set(object o,string n,object v)=>o.GetType().GetField(n,F).SetValue(o,v);object Call(object o,string n,params object[] a)=>o.GetType().GetMethods(F).Single(m=>m.Name==n&&m.GetParameters().Length==a.Length).Invoke(o,a);
 var owner=new GameObject("Owned progression check");owner.SetActive(false);var runtime=owner.AddComponent<EchoSphereRuntime>();runtime.enabled=false;owner.SetActive(true);Set(runtime,"_knowledgeLoaded",true);Set(runtime,"_shopSaveLoaded",true);Set(runtime,"_shopSave",Activator.CreateInstance(typeof(EchoSphereRuntime).GetNestedType("ShopSaveData",F)));var catalog=Resources.Load<NativeArchiveCatalog>("EchoSphere/NativeArchiveCatalog");Set(runtime,"_sourceKnowledge",catalog);Set(runtime,"_knowledgeSection","artifacts");var known=(HashSet<string>)typeof(EchoSphereRuntime).GetField("_knownKnowledgeIds",F).GetValue(runtime);var run=NativeRunCatalog.Instance;
 var screens=new List<NativeArchiveScreen.State>();
 NativeArchiveScreen.Card Project(string section,string id,bool ru){Set(runtime,"_knowledgeSection",section);var state=(NativeArchiveScreen.State)Call(runtime,"ReadNativeArchiveState");var card=state.Cards.Single(c=>c.Id==id);Call(runtime,"BindArchiveProgression",card,ru);return card;}
 void Closed(NativeArchiveScreen.ProgressionChoice c){Check(!c.Open&&c.Title==null&&c.Description==null,"unselected mutation has no spoiler text");}
 try{foreach(bool ru in new[]{true,false}){
 foreach(var sphere in run.Spheres){known.Clear();known.Add("sphere:"+sphere.Id);var card=Project("spheres","sphere:"+sphere.Id,ru);Check(card.Progression.Branches.Count==sphere.Branches.Count,"all sphere branches");foreach(var b in card.Progression.Branches){Closed(b);Check(b.Finals.Count==0,"hidden parent does not reveal final contents");}
 foreach(var branch in sphere.Branches){known.Clear();known.Add("sphere:"+sphere.Id);known.Add("sphere-branch:"+branch.Id);for(int i=0;i<branch.FinalCards.Count;i++){known.Add("sphere-final:"+sphere.Id+":"+branch.Id+":"+i);card=Project("spheres","sphere:"+sphere.Id,ru);var opened=card.Progression.Branches.Single(b=>b.Open);Check(opened.Title==branch.Name(ru),"selected sphere branch name");for(int j=0;j<opened.Finals.Count;j++){if(i==j)Check(opened.Finals[j].Open&&opened.Finals[j].Title==branch.FinalCards[j].Name(ru),"exact selected sphere final");else Closed(opened.Finals[j]);}Check(card.Progression.Branches.Count(b=>b.Open)==1,"unselected sibling branches stay hidden");known.Remove("sphere-final:"+sphere.Id+":"+branch.Id+":"+i);}}
 }
 foreach(var ability in run.Abilities){known.Clear();known.Add("ability:"+ability.Id);var card=Project("abilities","ability:"+ability.Id,ru);foreach(var b in card.Progression.Branches)Closed(b);foreach(var branch in ability.Branches){known.Clear();known.Add("ability:"+ability.Id);known.Add("ability-evolution:"+branch.Id);var finals=branch.HasFinalPool?branch.Finals:ability.FallbackFinals;foreach(var final in finals){known.Add("ability-evolution:"+final.Id);card=Project("abilities","ability:"+ability.Id,ru);var opened=card.Progression.Branches.Single(b=>b.Open);Check(opened.Title==branch.Name(ru),"selected ability branch");for(int j=0;j<opened.Finals.Count;j++){if(finals[j].Id==final.Id)Check(opened.Finals[j].Open&&opened.Finals[j].Title==final.Name(ru),"exact selected ability final");else Closed(opened.Finals[j]);}known.Remove("ability-evolution:"+final.Id);}}}
 foreach(var link in run.SphereAbilityLinks){known.Clear();known.Add("sphere:"+link.Sphere);known.Add("ability:"+link.Ability);var card=Project("spheres","sphere:"+link.Sphere,ru);foreach(var l in card.Progression.Links)Closed(l);known.Add("sphere-branch:"+link.Branch);string final=link.AbilityFinal;int at=final.LastIndexOf("_f",StringComparison.Ordinal);var kind=(RunUpgradeKind)Call(runtime,"PlannerAbility",link.Ability);var actual=LevelUpAbilityRules.GetActiveAbilityEvolutionChoices(kind,true,final.Substring(0,at))[final[final.Length-1]-'1'];known.Add("ability-evolution:"+actual.Id);var sphereCard=Project("spheres","sphere:"+link.Sphere,ru);var abilityCard=Project("abilities","ability:"+link.Ability,ru);Check(sphereCard.Progression.Links.Any(l=>l.Open&&l.Title==link.Name(ru)&&l.Description==link.Description(ru)),"selected exact synergy revealed from sphere");Check(abilityCard.Progression.Links.Any(l=>l.Open&&l.Title==link.Name(ru)),"same synergy revealed from ability");}
 known.Clear();var sample=run.Spheres[0];var branchSample=sample.Branches[0];known.Add("sphere:"+sample.Id);known.Add("sphere-branch:"+branchSample.Id);known.Add("sphere-final:"+sample.Id+":"+branchSample.Id+":1");foreach(var link in run.SphereAbilityLinks.Where(l=>l.Sphere==sample.Id)){known.Add("ability:"+link.Ability);}
 var display=Project("spheres","sphere:"+sample.Id,ru);screens.Add(new NativeArchiveScreen.State{Russian=ru,Section="spheres",Query="",Known=known.Count,Cards=new[]{display}});
 known.Clear();var abilitySample=run.Abilities.First(a=>a.Branches.Count>0);var abilityBranch=abilitySample.Branches[0];known.Add("ability:"+abilitySample.Id);known.Add("ability-evolution:"+abilityBranch.Id);var abilityFinals=abilityBranch.HasFinalPool?abilityBranch.Finals:abilitySample.FallbackFinals;known.Add("ability-evolution:"+abilityFinals[1].Id);var abilityDisplay=Project("abilities","ability:"+abilitySample.Id,ru);screens.Add(new NativeArchiveScreen.State{Russian=ru,Section="abilities",Query="",Known=known.Count,Cards=new[]{abilityDisplay}});
 }
 // Actual accepted choice records discovery immediately, without the periodic knowledge tick.
 known.Clear();var options=(List<SphereEvolutionOption>)typeof(EchoSphereRuntime).GetField("_evolutionChoices",F).GetValue(runtime);var choice=SphereEvolutionCatalog.GetBranches(SphereId.Standard)[0];options.Clear();options.Add(choice);Set(runtime,"_choosingEvolution",true);Set(runtime,"_pendingEvolutionSphere",SphereId.Standard);Set(runtime,"_pendingFinalEvolution",false);Set(runtime,"_pendingEvolutionIsAbility",false);Call(runtime,"ChooseEvolution",0);Check(known.Contains("sphere-branch:"+choice.Id),"accepted choice immediately discovers branch");
 }
 catch{UnityEngine.Object.DestroyImmediate(owner);throw;}
 var host=new GameObject("Owned progression screen");var archive=host.AddComponent<NativeArchiveScreen>();var target=new RenderTexture(720,1400,0,RenderTextureFormat.ARGB32);target.Create();int language=0,frames=0,last=-1;double deadline=EditorApplication.timeSinceStartup+120;UIDocument doc=null;VisualElement root=null;EditorApplication.CallbackFunction tick=null;
 void Show(){archive.Show(screens[language],Screen.width/360f,()=>{},_=>{},_=>{});doc=host.GetComponent<UIDocument>();doc.panelSettings.scaleMode=PanelScaleMode.ConstantPixelSize;doc.panelSettings.scale=2;doc.panelSettings.targetTexture=target;root=doc.rootVisualElement;root.style.width=360;root.style.height=700;frames=0;}
 void Finish(string status,string error=null){EditorApplication.update-=tick;doc.panelSettings.targetTexture=null;UnityEngine.Object.DestroyImmediate(host);UnityEngine.Object.DestroyImmediate(owner);target.Release();UnityEngine.Object.DestroyImmediate(target);Directory.CreateDirectory("Library/menu-archive");File.WriteAllText("Library/menu-archive/progression.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{status,checks,error,scope="all sphere and ability branch/final discovery permutations, reciprocal synergies and immediate accepted choice; RU/EN attached click and no-spoiler detail; no PlayerPrefs writes"}));}
 Show();Application.runInBackground=true;tick=()=>{try{EditorApplication.QueuePlayerLoopUpdate();if(!Application.isPlaying||EditorApplication.timeSinceStartup>deadline){Finish("FAIL","deadline");return;}if(last==Time.frameCount)return;last=Time.frameCount;frames++;if(frames==20){var card=root.Query<VisualElement>("archive-card").ToList()[0];using(var click=ClickEvent.GetPooled()){click.target=card;card.SendEvent(click);}Check(root.Q("archive-entry-detail")!=null,"tap opens sphere or ability detail");}if(frames<36)return;
 var detail=root.Q("archive-entry-detail");Check(detail.Q("archive-progression-title")!=null,"progression section visible");Check(detail.Query<VisualElement>("archive-progression-branch").ToList().Count>0,"progression branches visible");foreach(var label in detail.Query<Label>().ToList()){if(label.worldBound.width<=0)continue;Check(label.worldBound.xMin>=root.worldBound.xMin-1&&label.worldBound.xMax<=root.worldBound.xMax+1,"text horizontal bounds");}
 var prior=RenderTexture.active;var image=new Texture2D(target.width,target.height,TextureFormat.RGBA32,false);try{RenderTexture.active=target;image.ReadPixels(new Rect(0,0,target.width,target.height),0,0);image.Apply();Directory.CreateDirectory("Library/menu-archive");File.WriteAllBytes("Library/menu-archive/progression-"+(screens[language].Section+"-"+(screens[language].Russian?"ru":"en"))+".png",image.EncodeToPNG());}finally{RenderTexture.active=prior;UnityEngine.Object.DestroyImmediate(image);}if(++language==screens.Count){Finish("PASS");return;}Show();}catch(Exception e){Finish("FAIL",e.ToString());}};EditorApplication.update+=tick;return new{status="queued",checks};
 }
}
